def solve(g):
    H,W=len(g),len(g[0])
    fr=[i for i in range(H) if all(v==2 for v in g[i])][0]
    step=-1 if fr==0 else 1
    seen=[[False]*W for _ in range(H)]; objs=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] not in (0,2) and not seen[i][j]:
                col=g[i][j]; st=[(i,j)]; comp=[]; seen[i][j]=True
                while st:
                    y,x=st.pop(); comp.append([y,x])
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==col:
                            seen[ny][nx]=True; st.append((ny,nx))
                objs.append([comp,col])
    occupied={(i,j) for i in range(H) for j in range(W) if g[i][j] not in (0,2)}
    occupied|={(fr,j) for j in range(W)}
    while True:
        moved=False
        for obj,col in objs:
            cells={tuple(c) for c in obj}
            newc=[(y+step,x) for y,x in obj]
            if all(0<=y<H and ((y,x) not in occupied or (y,x) in cells) for y,x in newc):
                for c in obj: occupied.discard(tuple(c))
                for c in newc: occupied.add(c)
                for k,c in enumerate(newc): obj[k]=list(c)
                moved=True
        if not moved: break
    out=[[0]*W for _ in range(H)]
    out[fr]=[2]*W
    for obj,col in objs:
        for y,x in obj: out[y][x]=col
    return out

